<?php
require "auth.php"; $pageTitle="Suppliers"; $active="suppliers";
if(isset($_POST['save'])){$id=(int)($_POST['id']??0);$n=trim($_POST['name']);$ph=trim($_POST['phone']);$ad=trim($_POST['address']);if($id){$s=$conn->prepare("UPDATE suppliers SET name=?,phone=?,address=? WHERE id=?");$s->bind_param("sssi",$n,$ph,$ad,$id);}else{$s=$conn->prepare("INSERT INTO suppliers(name,phone,address) VALUES(?,?,?)");$s->bind_param("sss",$n,$ph,$ad);}$s->execute();header("Location: suppliers.php");exit;}
if(isset($_GET['delete'])){$conn->query("DELETE FROM suppliers WHERE id=".(int)$_GET['delete']);header("Location: suppliers.php");exit;}
$edit=null;if(isset($_GET['edit']))$edit=$conn->query("SELECT * FROM suppliers WHERE id=".(int)$_GET['edit'])->fetch_assoc();
require "partials/header.php"; ?>
<div class="panel"><h3><?= $edit?'Edit Supplier':'Add Supplier' ?></h3><form method="post"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Supplier Name</label><input name="name" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label>Address</label><input name="address" value="<?=e($edit['address']??'')?>"></div></div><div class="form-actions"><button class="btn primary" name="save">Save Supplier</button></div></form></div>
<div class="panel" style="margin-top:20px"><h3>Supplier List</h3><table class="table"><tr><th>Name</th><th>Phone</th><th>Address</th><th>Actions</th></tr><?php $rs=$conn->query("SELECT * FROM suppliers ORDER BY name");while($r=$rs->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td><a class="btn btn-sm secondary" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-sm danger-btn" data-confirm="Delete supplier?" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></table></div>
